Lemma fire_1RB0RC_0LB1RC_1LB1RD_0LA1LA : forall t, ~ In t pins_1RB0RC_0LB1RC_1LB1RD_0LA1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
