      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RC_0LB1RC_1LB1RD_0LA1LA
      with (l := [SWin 1]).
    vm_compute; reflexivity.
