      with (l := [SWin 4]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RC_0LB1RC_1LB1RD_0LA1LA
      with (l := [SWin 5; SWin 2; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RC_0LB1RC_1LB1RD_0LA1LA
      with (l := [SWin 5]).
