  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RC_0LB1RC_1LD0RC_0LB1RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RC_0LB1RC_1LD0RC_0LB1RA p j E)].
