Proof. intros p j q0 E. destruct (lapi_1RB0RC_0RC0LD_0RD0RB_1LD1RA p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0RC_0RC0LD_0RD0RB_1LD1RA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0RC_0RC0LD_0RD0RB_1LD1RA p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_1RB0RC_0RC0LD_0RD0RB_1LD1RA).
    split; [lia|]. split; [| exact (gbo_1RB0RC_0RC0LD_0RD0RB_1LD1RA j)].
    rewrite (gso_1RB0RC_0RC0LD_0RD0RB_1LD1RA p j E).
    exact (srun_sound tm true true chb_1RB0RC_0RC0LD_0RD0RB_1LD1RA B0_1RB0RC_0RC0LD_0RD0RB_1LD1RA BB1_1RB0RC_0RC0LD_0RD0RB_1LD1RA 4 6
             run_boot_1RB0RC_0RC0LD_0RD0RB_1LD1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 10), (cden [] [] j B1_1RB0RC_0RC0LD_0RD0RB_1LD1RA).
    split; [| exact (geo_1RB0RC_0RC0LD_0RD0RB_1LD1RA p j E)].
    rewrite (gxi_1RB0RC_0RC0LD_0RD0RB_1LD1RA j).
    exact (srun_sound tm true true che_1RB0RC_0RC0LD_0RD0RB_1LD1RA BE0_1RB0RC_0RC0LD_0RD0RB_1LD1RA B1_1RB0RC_0RC0LD_0RD0RB_1LD1RA 4 10
             run_exit_1RB0RC_0RC0LD_0RD0RB_1LD1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
