(** ** The lap *)

Lemma lap_1RB0RC_0RC0LD_0RD0RB_1LD1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RC_0RC0LD_0RD0RB_1LD1RA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0RC_0RC0LD_0RD0RB_1LD1RA p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0RC_0RC0LD_0RD0RB_1LD1RA : stepn tmm_1RB0RC_0RC0LD_0RD0RB_1LD1RA 5 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB0RC_0RC0LD_0RD0RB_1LD1RA 5 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0RC_0RC0LD_0RD0RB_1LD1RA 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0RC_0RC0LD_0RD0RB_1LD1RA : existsb (fun tg => cfires tmm_1RB0RC_0RC0LD_0RD0RB_1LD1RA c0 5 tg) pins_1RB0RC_0RC0LD_0RD0RB_1LD1RA = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RC_0RC0LD_0RD0RB_1LD1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RC_0RC0LD_0RD0RB_1LD1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RC_0RC0LD_0RD0RB_1LD1RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RC_0RC0LD_0RD0RB_1LD1RA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB0RC_0RC0LD_0RD0RB_1LD1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0RC_0RC0LD_0RD0RB_1LD1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0RC_0RC0LD_0RD0RB_1LD1RA t p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_1RB0RC_0RC0LD_0RD0RB_1LD1RA). split;
      [| exact (gbo_1RB0RC_0RC0LD_0RD0RB_1LD1RA j)].
    rewrite (gso_1RB0RC_0RC0LD_0RD0RB_1LD1RA p j E).
    exact (srun_sound tm true true chb_1RB0RC_0RC0LD_0RD0RB_1LD1RA B0_1RB0RC_0RC0LD_0RD0RB_1LD1RA BB1_1RB0RC_0RC0LD_0RD0RB_1LD1RA 4 6
             run_boot_1RB0RC_0RC0LD_0RD0RB_1LD1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0RC_0RC0LD_0RD0RB_1LD1RA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0RC_0RC0LD_0RD0RB_1LD1RA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RC_0RC0LD_0RD0RB_1LD1RA : forall t, ~ In t pins_1RB0RC_0RC0LD_0RD0RB_1LD1RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RC_0RC0LD_0RD0RB_1LD1RA.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0RC_0RC0LD_0RD0RB_1LD1RA
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0RC_0RC0LD_0RD0RB_1LD1RA (StB, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0RC_0RC0LD_0RD0RB_1LD1RA [SWin 2; SRotL 1; SWin 1; SCycL 2 0; SWinL 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RC_0RC0LD_0RD0RB_1LD1RA
      with (l := [SWin 2; SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0RC_0RC0LD_0RD0RB_1LD1RA (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0RC_0RC0LD_0RD0RB_1LD1RA [SWin 2; SRotL 1; SWin 1; SCycL 2 0; SWinL 2] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RC_0RC0LD_0RD0RB_1LD1RA
      with (l := [SWin 2; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RC_0RC0LD_0RD0RB_1LD1RA
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RC_0RC0LD_0RD0RB_1LD1RA
      with (l := [SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem qhtrm_1RB0RC_0RC0LD_0RD0RB_1LD1RA : NonHalt tmm_1RB0RC_0RC0LD_0RD0RB_1LD1RA /\ QHBoundTr 32779478 tmm_1RB0RC_0RC0LD_0RD0RB_1LD1RA /\ QuasiHaltsTr tmm_1RB0RC_0RC0LD_0RD0RB_1LD1RA.
Proof.
  apply (lap_qh_stage tmm_1RB0RC_0RC0LD_0RD0RB_1LD1RA pins_1RB0RC_0RC0LD_0RD0RB_1LD1RA Cc 1 5 32779478).
  - exact bootq_1RB0RC_0RC0LD_0RD0RB_1LD1RA.
  - intros p _. apply lap_1RB0RC_0RC0LD_0RD0RB_1LD1RA.
  - intros t Ht p _. apply fire_1RB0RC_0RC0LD_0RD0RB_1LD1RA. exact Ht.
  - exact wit_1RB0RC_0RC0LD_0RD0RB_1LD1RA.
  - apply qcleb_QC_15. reflexivity.
Qed.

Theorem qhtr_1RB0RC_0RC0LD_0RD0RB_1LD1RA : NonHalt tm_1RB0RC_0RC0LD_0RD0RB_1LD1RA /\ QHBoundTr 32779478 tm_1RB0RC_0RC0LD_0RD0RB_1LD1RA /\ QuasiHaltsTr tm_1RB0RC_0RC0LD_0RD0RB_1LD1RA.
