Lemma gp_1RB0RC_1LA0RD_0LC0RB_1LC0RD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j P0_1RB0RC_1LA0RD_0LC0RB_1LC0RD /\
