  unfold Cc_1RB0RC_1LA0RD_0LC0RB_1LC0RD, cden, P0_1RB0RC_1LA0RD_0LC0RB_1LC0RD, P1_1RB0RC_1LA0RD_0LC0RB_1LC0RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
