    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RC_1LA0RD_0LC0RB_1LC0RD [SWinR 3] (StD, S1) ltac:(vm_compute; reflexivity)
