Theorem qhtrm_1RB0RC_1LA0RD_0LC0RB_1LC0RD : NonHalt tmm_1RB0RC_1LA0RD_0LC0RB_1LC0RD /\ QHBoundTr 32779478 tmm_1RB0RC_1LA0RD_0LC0RB_1LC0RD /\ QuasiHaltsTr tmm_1RB0RC_1LA0RD_0LC0RB_1LC0RD.
