Theorem qhtr_1RB0RC_1LA0RD_0LC0RB_1LC0RD : NonHalt tm_1RB0RC_1LA0RD_0LC0RB_1LC0RD /\ QHBoundTr 32779478 tm_1RB0RC_1LA0RD_0LC0RB_1LC0RD /\ QuasiHaltsTr tm_1RB0RC_1LA0RD_0LC0RB_1LC0RD.
