(** 1RB0RC_1LA0RD_0LC0RB_1LC1RD *)
(** 1RB0RC_1LA0RD_0LC0RB_1LC1RD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0RC_1LA0RD_0LC0RB_1LC1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S0 DL StC | StC, S1 => mk S0 DR StB
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S1 DR StD end.

(** Its mirror 1LB0LC_1RA0LD_0RC0LB_1RC1LD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0RC_1LA0RD_0LC0RB_1LC1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S0 DL StD
  | StC, S0 => mk S0 DR StC | StC, S1 => mk S0 DL StB
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S1 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0RC_1LA0RD_0LC0RB_1LC1RD : list Instr := [(StA, S1)].
Definition tmw_1RB0RC_1LA0RD_0LC0RB_1LC1RD : TM := tm_wrap_trs tmm_1RB0RC_1LA0RD_0LC0RB_1LC1RD pins_1RB0RC_1LA0RD_0LC0RB_1LC1RD.
