Lemma mirror_ok_1RB0RC_1LA0RD_0LC0RB_1LC1RD : mirror_tm tm_1RB0RC_1LA0RD_0LC0RB_1LC1RD = tmm_1RB0RC_1LA0RD_0LC0RB_1LC1RD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

