Lemma lapi_1RB0RC_1LA1RC_1LD0RB_0RC0LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0RC_1LA1RC_1LD0RB_0RC0LD p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0RC_1LA1RC_1LD0RB_0RC0LD Z0_1RB0RC_1LA1RC_1LD0RB_0RC0LD Z1_1RB0RC_1LA1RC_1LD0RB_0RC0LD 0 2
               run_z_1RB0RC_1LA1RC_1LD0RB_0RC0LD (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0RC_1LA1RC_1LD0RB_0RC0LD p j' q0 E) as (HA & HB).
    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0RC_1LA1RC_1LD0RB_0RC0LD P0_1RB0RC_1LA1RC_1LD0RB_0RC0LD P1_1RB0RC_1LA1RC_1LD0RB_0RC0LD 6 8
               run_p_1RB0RC_1LA1RC_1LD0RB_0RC0LD (Ap_Alph_00_10_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB0RC_1LA1RC_1LD0RB_0RC0LD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0RC_1LA1RC_1LD0RB_0RC0LD.
