    intros p1 j1 E1.
    exact (firex_1RB0RC_1LB1RA_0RD0LB_0RB0RC [SWin 8; SCycL 2 0; SWin 1; SWinL 2] (StD, S0) ltac:(vm_compute; reflexivity)
